class GradientPage extends StatelessWidget { const GradientPage({super.key,required this.child}); final Widget child; @override Widget build(BuildContext c)=>Container(width:double.infinity,height:double.infinity,decoration:BoxDecoration(gradient:RadialGradient(radius:1.1,center:Alignment.topCenter,colors:[Theme.of(c).colorScheme.primary.withValues(alpha:.10),Theme.of(c).scaffoldBackgroundColor])),child:SafeArea(child:SingleChildScrollView(padding:const EdgeInsets.all(20),child:Center(child:child))));}
