class ChoiceCard extends StatelessWidget { const ChoiceCard({super.key,required this.icon,required this.title,required this.subtitle,required this.onTap}); final IconData icon; final String title,subtitle; final VoidCallback onTap; @override Widget build(BuildContext c)=>InkWell(borderRadius:BorderRadius.circular(18),onTap:onTap,child:Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(border:Border.all(color:Theme.of(c).colorScheme.outline),borderRadius:BorderRadius.circular(18)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[CircleAvatar(backgroundColor:Theme.of(c).colorScheme.surfaceContainerHighest,child:Icon(icon,color:Theme.of(c).colorScheme.primary)),const SizedBox(height:10),Text(title,style:const TextStyle(fontWeight:FontWeight.w700)),const SizedBox(height:4),Text(subtitle,style:Theme.of(c).textTheme.bodySmall)])));}
class InfoCard extends StatelessWidget { const InfoCard({super.key,required this.title,required this.rows}); final String title; final Map<String,String> rows; @override Widget build(BuildContext c)=>Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:Theme.of(c).colorScheme.surface,border:Border.all(color:Theme.of(c).colorScheme.outline),borderRadius:BorderRadius.circular(18)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontWeight:FontWeight.w700)),...rows.entries.map((e)=>Padding(padding:const EdgeInsets.symmetric(vertical:7),child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(e.key,style:TextStyle(color:Theme.of(c).colorScheme.onSurfaceVariant)),Flexible(child:Text(e.value,style:const TextStyle(fontWeight:FontWeight.w600),textAlign:TextAlign.right))]))) ]));}
class DiiaQr extends StatelessWidget { const DiiaQr({super.key}); @override Widget build(BuildContext c)=>Container(width:220,height:220,padding:20,decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(20)),child:CustomPaint(painter:_QrPainter()));}
class _QrPainter extends CustomPainter { @override void paint(Canvas canvas,Size size){final p=Paint()..color=Colors.black; final r=Random(7); final n=11; final s=size.width/n; for(int y=0;y<n;y++){for(int x=0;x<n;x++){if(r.nextBool())canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(x*s,y*s,s-2,s-2),const Radius.circular(1)),p);}}} @override bool shouldRepaint(covariant CustomPainter old)=>false;}
